 rig.arm=new THREE.Group();rig.arm.position.set(isEnemy?.34:-.34,1.43,0);root.add(rig.arm);
 box(rig.arm,.19,.52,.2,isEnemy?red:cloth,0,-.17,0);sphere(rig.arm,.13,isEnemy?skin:skin,0,-.46,0,.9,.85,.9);
