 cylinder(sword,.035,.04,.32,wood,0,-.12,0,6);box(sword,.055,.045,.36,gold,0,-.3,0);const length=isEnemy?1.18:.88;const bladeMesh=box(sword,isEnemy?.105:.065,length,.035,blade,0,-.32-length/2,0);bladeMesh.rotation.z=isEnemy?-.035:-.04;rig.sword=sword;
 if(isEnemy){const hat=new THREE.Mesh(new THREE.ConeGeometry(.42,.14,8),dark);hat.position.set(0,2.1,0);root.add(hat);box(root,.75,.07,.07,gold,0,2.02,0)}
 root.position.y=0;rig.isEnemy=isEnemy;rig.sword.visible=true;return rig}
