 if(type==='heal'&&heals>0&&playerHp<100&&playerAction<=0){heals--;playerHp=Math.min(100,playerHp+34);playerAction=.55;playerActionType='heal';updateHUD();say('A BREATH RECLAIMED',1)}
}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyJ'||e.code==='Enter')action('attack');if(e.code==='KeyK')action('parry');if(e.code==='Space')action('dodge');if(e.code==='KeyH')action('heal')});window.addEventListener('keyup',e=>keys[e.code]=false);
