document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir;b.addEventListener('pointerdown',e=>{e.preventDefault();keys['Dir'+dir]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys['Dir'+dir]=false))});
function damagePlayer(amount,posture){if(invuln>0)return;playerHp=Math.max(0,playerHp-amount);playerPost=clamp(playerPost+posture,0,100);shake=.3;flash.position.copy(player.root.position).add(new THREE.Vector3(0,1.3,0));flash.intensity=10;say('STEEL ON FLESH',.55);if(playerHp<=0)outcome(false);updateHUD()}
function perfectDeflect(){enemyPost=clamp(enemyPost+34,0,100);playerPost=Math.max(0,playerPost-16);enemyState='stagger';enemyTimer=.9;enemy.root.rotation.z=.16;shake=.18;flash.position.copy(enemy.root.position).add(new THREE.Vector3(0,1.4,0));flash.intensity=15;say('PERFECT DEFLECT',.85);updateHUD();if(enemyPost>=100)outcome(true)}
function enemyLogic(dt,dist){enemyTimer-=dt;
 if(enemyState==='approach'){
  if(dist>1.8){const dx=player.root.position.x-enemy.root.position.x,dz=player.root.position.z-enemy.root.position.z;enemy.root.position.x+=dx/dist*Math.min(1.05*dt,dist-1.72);enemy.root.position.z+=dz/dist*Math.min(1.05*dt,dist-1.72)}
  if(enemyTimer<=0){enemyState='tell';enemyAttackTimer=.78;enemyTimer=.78;enemyAttackType=(Math.random()<.25?'heavy':'cut');enemyHitDone=false;say(enemyAttackType==='heavy'?'HEAVY CUT':'READ THE FLASH',.6)}
 }else if(enemyState==='tell'){
  enemyAttackTimer-=dt;enemy.root.position.y=Math.sin(time*16)*.035;
  if(enemyTimer<=0){enemyState='strike';enemyTimer=.26;enemyAttackTimer=0}
 }else if(enemyState==='strike'){
  enemy.root.rotation.z=Math.sin(Math.min(1,(.26-enemyTimer)/.26)*Math.PI)*-.16;
  if(!enemyHitDone){enemyHitDone=true;const d=player.root.position.distanceTo(enemy.root.position);
   if(d<2.35){if(playerActionType==='parry'&&playerAction>.01){perfectDeflect()}else if(invuln>0){say('STEP THROUGH',.45)}else{damagePlayer(enemyAttackType==='heavy'?23:15,enemyAttackType==='heavy'?26:18)}}
  }
  if(enemyState==='strike'&&enemyTimer<=0){enemyState='recover';enemyTimer=.85;enemy.root.rotation.z=0}
 }else if(enemyState==='recover'){if(enemyTimer<=0){enemyState='approach';enemyTimer=.6}}
 else if(enemyState==='stagger'){enemy.root.rotation.z*=Math.max(0,1-dt*3);if(enemyTimer<=0){enemyState='recover';enemyTimer=.55}}
}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-last)/1000||.016);last=now;time+=dt;
 if(state==='play'){
  if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)$('#message').classList.remove('show')}
  if(playerAction>0){playerAction=Math.max(0,playerAction-dt);if(playerAction===0)playerActionType=''}if(invuln>0)invuln-=dt;if(comboWindow>0)comboWindow-=dt;
  const forward=(keys.KeyW||keys.ArrowUp||keys.Dirup?1:0)-(keys.KeyS||keys.ArrowDown||keys.Dirdown?1:0),side=(keys.KeyD||keys.ArrowRight||keys.Dirright?1:0)-(keys.KeyA||keys.ArrowLeft||keys.Dirleft?1:0);let mx=side,mz=-forward;const ml=Math.hypot(mx,mz);if(ml){mx/=ml;mz/=ml;const speed=playerActionType==='dodge'?5.8:3.25;player.root.position.x=clamp(player.root.position.x+mx*speed*dt,-5.7,5.7);player.root.position.z=clamp(player.root.position.z+mz*speed*dt,-5.5,5.3);walkPhase+=dt*10;player.root.rotation.y=Math.atan2(-mx,mz);player.root.position.y=Math.abs(Math.sin(walkPhase))*.045}
  const dx=enemy.root.position.x-player.root.position.x,dz=enemy.root.position.z-player.root.position.z,dist=Math.hypot(dx,dz);const face=Math.atan2(-dx,-dz);player.root.rotation.y=THREE.MathUtils.dampAngle(player.root.rotation.y,face,5,dt);enemy.root.rotation.y=Math.atan2(dx,dz);
  if(playerActionType==='attack'&&playerAction<.2&&!player.attackDone){player.attackDone=true;if(dist<2.5){const damage=17+(combo?3:0);enemyHp=Math.max(0,enemyHp-damage);enemyPost=clamp(enemyPost+14+(combo?4:0),0,100);shake=.1;flash.position.copy(enemy.root.position).add(new THREE.Vector3(0,1.3,0));flash.intensity=8;say(combo===2?'THREE BEATS':'CLEAN STRIKE',.5);if(enemyHp<=0)outcome(true);if(enemyPost>=100)outcome(true);updateHUD()}}
  if(playerActionType!=='attack')player.attackDone=false;
  if(playerActionType==='attack'){player.arm.rotation.x=-.8;player.arm.rotation.z=.35+Math.sin((.34-playerAction)*16)*.35;slash.position.set(player.root.position.x,1.15,player.root.position.z-.2);slash.rotation.y=player.root.rotation.y;slash.visible=playerAction>.08}else if(playerActionType==='parry'){player.arm.rotation.x=-1.05;player.arm.rotation.z=-.42;slash.visible=false}else if(playerActionType==='dodge'){player.root.rotation.z=.24;slash.visible=false}else{player.arm.rotation.x=0;player.arm.rotation.z=0;player.root.rotation.z*=Math.max(0,1-dt*8);slash.visible=false}
  if(enemyState==='tell'){enemy.arm.rotation.x=-1.25;enemy.arm.rotation.z=-.45;enemy.root.position.y=.04+Math.sin(time*19)*.035}
  else if(enemyState==='strike'){enemy.arm.rotation.x=.8;enemy.arm.rotation.z=.42}
  else {enemy.arm.rotation.x=0;enemy.arm.rotation.z=0;if(enemyState!=='tell')enemy.root.position.y=0}
  enemyLogic(dt,dist);
  playerPost=Math.max(0,playerPost-dt*2.7);enemyPost=Math.max(0,enemyPost-dt*1.3);
  if(playerPost>=100){damagePlayer(10,30);playerPost=55;say('POSTURE BROKEN',.8)}
  motes.rotation.y=Math.sin(time*.12)*.08;flash.intensity=Math.max(0,flash.intensity-dt*35);
  const target=new THREE.Vector3((player.root.position.x+enemy.root.position.x)*.5,0,(player.root.position.z+enemy.root.position.z)*.5);camera.position.x=THREE.MathUtils.damp(camera.position.x,target.x,2.4,dt);camera.position.z=THREE.MathUtils.damp(camera.position.z,target.z+9,2.4,dt);camera.position.y=THREE.MathUtils.damp(camera.position.y,5.2,2,dt);camera.lookAt(target.x,.7,target.z-.35);if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.y+=(Math.random()-.5)*shake;shake=Math.max(0,shake-dt*.7)}
  if(Math.floor(now/150)!==Math.floor((now-dt*1000)/150))updateHUD();
 }else {camera.lookAt(0,.5,-.4);motes.rotation.y+=dt*.015}
 renderer.render(scene,camera)
}
player.attackDone=false;
requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script></body></html>

